# Winston Logger - Quick Start Examples

## Basic Usage in Services

```typescript
import { Injectable } from '@nestjs/common';
import { LoggerService } from '../../common/logger';

@Injectable()
export class ExampleService {
  // Create logger instance with context
  private readonly logger = new LoggerService('ExampleService');

  async performOperation(userId: string) {
    // Info level - general flow
    this.logger.log(`Starting operation for user ${userId}`);

    try {
      const result = await this.heavyOperation();

      // Success logging
      this.logger.log(`Operation completed successfully for user ${userId}`);

      return result;
    } catch (error: any) {
      // Error logging with stack trace
      this.logger.error(
        `Operation failed for user ${userId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  async heavyOperation() {
    // Debug level - detailed execution info
    this.logger.debug('Entering heavyOperation');

    // Warn level - non-critical issues
    if (!this.cache.isValid()) {
      this.logger.warn('Cache is stale, falling back to database');
    }

    // ... implementation ...
  }
}
```

## Usage in Controllers

```typescript
import { Controller, Get, Post, Body, Param } from '@nestjs/common';
import { LoggerService } from '../../common/logger';

@Controller('users')
export class UsersController {
  private readonly logger = new LoggerService('UsersController');

  constructor(private usersService: UsersService) {}

  @Get()
  findAll() {
    this.logger.log('GET /users - Fetching all users');
    return this.usersService.findAll();
  }

  @Post()
  create(@Body() createUserDto: CreateUserDto) {
    this.logger.log(`POST /users - Creating user: ${createUserDto.email}`);

    try {
      const user = await this.usersService.create(createUserDto);
      this.logger.log(`User created successfully: ${user.id}`);
      return user;
    } catch (error: any) {
      this.logger.error(`Failed to create user: ${error.message}`, error.stack);
      throw error;
    }
  }

  @Get(':id')
  findOne(@Param('id') id: string) {
    this.logger.debug(`GET /users/${id} - Fetching user details`);
    return this.usersService.findOne(id);
  }
}
```

## Advanced: Contextual Metadata

```typescript
import { LoggerService } from '../../common/logger';

@Injectable()
export class PaymentService {
  private readonly logger = new LoggerService('PaymentService');

  async processPayment(orderId: string, amount: number) {
    // Get Winston instance for advanced features
    const winston = this.logger.getWinstonLogger();

    // Log with additional metadata (appears in JSON logs)
    winston.info('Processing payment', {
      orderId,
      amount,
      currency: 'USD',
      timestamp: new Date().toISOString(),
    });

    try {
      const result = await this.paymentGateway.charge(amount);

      winston.info('Payment successful', {
        orderId,
        transactionId: result.id,
        amount,
      });

      return result;
    } catch (error: any) {
      winston.error('Payment failed', {
        orderId,
        amount,
        error: error.message,
        stack: error.stack,
      });
      throw error;
    }
  }
}
```

## Best Practices

### ✅ Good Examples

```typescript
// Good: Context is clear
this.logger.log(`User ${userId} logged in from IP ${ip}`);

// Good: Include relevant identifiers
this.logger.error(`Failed to send email to ${email}: ${error.message}`, error.stack);

// Good: Use appropriate log level
this.logger.warn('Database connection pool at 90% capacity');
this.logger.debug(`Cache hit for key: ${key}`);

// Good: Structured metadata for analytics
winston.info('API response time', {
  endpoint: '/api/users',
  duration: 145,
  status: 200,
});
```

### ❌ Bad Examples

```typescript
// Bad: No context
this.logger.log('Success');  // Success at what?

// Bad: Using wrong log level
this.logger.error('User clicked button');  // Not an error!

// Bad: Logging sensitive data
this.logger.log(`User password: ${password}`);  // Security risk!

// Bad: Excessive logging in loops
for (let i = 0; i < 10000; i++) {
  this.logger.log(`Processing item ${i}`);  // Performance issue!
}

// Bad: Using console instead of logger
console.log('Still using console');  // Don't do this!
```

## Common Patterns

### Pattern 1: Try-Catch with Logging

```typescript
async performAction() {
  this.logger.log('Action started');

  try {
    const result = await this.dangerousOperation();
    this.logger.log('Action completed successfully');
    return result;
  } catch (error: any) {
    this.logger.error(`Action failed: ${error.message}`, error.stack);
    throw error;  // Re-throw after logging
  }
}
```

### Pattern 2: Conditional Warning

```typescript
async checkHealth() {
  const cpuUsage = await this.getCPUUsage();

  if (cpuUsage > 80) {
    this.logger.warn(`High CPU usage detected: ${cpuUsage}%`);
  }

  return { cpu: cpuUsage, status: cpuUsage > 80 ? 'warning' : 'ok' };
}
```

### Pattern 3: Debugging Complex Operations

```typescript
async complexCalculation(data: any[]) {
  this.logger.debug(`Starting calculation with ${data.length} items`);

  const step1 = this.processStep1(data);
  this.logger.debug(`Step 1 complete: ${step1.length} results`);

  const step2 = this.processStep2(step1);
  this.logger.debug(`Step 2 complete: ${step2.length} results`);

  const final = this.processStep3(step2);
  this.logger.debug(`Calculation complete: ${final.value}`);

  return final;
}
```

## Environment-Specific Logging

Development (default):
```bash
# All logs to console + files
LOG_LEVEL=debug npm run start:dev
```

Production:
```bash
# Only info/warn/error to files
LOG_LEVEL=info npm run start:prod

# Enable console in production (debugging)
CONSOLE_LOGS=true LOG_LEVEL=debug npm run start:prod
```

